// generated by `cargo xtask protocol` from crates/kiln-protocol, do not edit
import type { ChartState } from "./ChartState";
import type { DeckBox } from "./DeckBox";
import type { DeckCellRange } from "./DeckCellRange";
import type { DeckComment } from "./DeckComment";
import type { DeckFormat } from "./DeckFormat";
import type { DeckGuide } from "./DeckGuide";
import type { DeckHeaderFooter } from "./DeckHeaderFooter";
import type { DeckLayoutInfo } from "./DeckLayoutInfo";
import type { DeckMasterView } from "./DeckMasterView";
import type { DeckMotionState } from "./DeckMotionState";
import type { DeckRect } from "./DeckRect";
import type { DeckSectionInfo } from "./DeckSectionInfo";
import type { DeckShapeInfo } from "./DeckShapeInfo";
import type { DeckSlideInfo } from "./DeckSlideInfo";
import type { DeckSpelling } from "./DeckSpelling";
import type { NodeId } from "./NodeId";

/**
 * Everything the Deck chrome shows.
 */
export type DeckState = { 
/**
 * The slides.
 */
slides: Array<DeckSlideInfo>, 
/**
 * The sections (empty without sections).
 */
sections: Array<DeckSectionInfo>, 
/**
 * The slide on the stage.
 */
current: number, 
/**
 * The selected slides (the rail).
 */
selected: Array<number>, 
/**
 * Slide width in px.
 */
slide_width: number, 
/**
 * Slide height in px.
 */
slide_height: number, 
/**
 * `widescreen`, `standard` or `custom`.
 */
size_kind: string, 
/**
 * Shapes of the current slide, top first.
 */
shapes: Array<DeckShapeInfo>, 
/**
 * Selected shapes.
 */
selection: Array<NodeId>, 
/**
 * Text is being edited.
 */
editing: boolean, 
/**
 * Contextual tabs to show: `shape`, `picture`, `table`, `chart`.
 */
contexts: Array<string>, 
/**
 * Formatting of the selection or the text being edited.
 */
format: DeckFormat | null, 
/**
 * Size and position of the selection.
 */
selection_box: DeckBox | null, 
/**
 * The selected shape's alt text.
 */
alt_text: string | null, 
/**
 * The current theme's name.
 */
theme: string, 
/**
 * The bundled themes (the gallery).
 */
themes: Array<string>, 
/**
 * The current master's layouts.
 */
layouts: Array<DeckLayoutInfo>, 
/**
 * The current slide's layout.
 */
layout: NodeId | null, 
/**
 * The current slide's speaker notes.
 */
notes: string, 
/**
 * Guides shown.
 */
guides: boolean, 
/**
 * Gridlines shown.
 */
gridlines: boolean, 
/**
 * Notes pane shown.
 */
notes_visible: boolean, 
/**
 * The current slide's header and footer.
 */
header_footer: DeckHeaderFooter, 
/**
 * The current slide's background colour, when solid.
 */
background: string | null, 
/**
 * Background graphics hidden on the current slide.
 */
hide_graphics: boolean, 
/**
 * A shape is armed for drawing (Insert ▸ Shapes).
 */
armed: string | null, 
/**
 * Find found nothing more.
 */
find_done: boolean, 
/**
 * Where the caret is, in slide px, while editing (the input proxy goes there).
 */
caret: DeckRect | null, 
/**
 * The Transitions, Animations and Slide Show tabs.
 */
motion: DeckMotionState, 
/**
 * Chart Design and Format: the selected chart.
 */
chart: ChartState | null, 
/**
 * The current slide's comment threads.
 */
comments: Array<DeckComment>, 
/**
 * Comment threads in the presentation.
 */
comment_total: number, 
/**
 * The selected thread.
 */
comment: NodeId | null, 
/**
 * The misspelled word Spelling stopped at.
 */
spelling: DeckSpelling | null, 
/**
 * Spelling went through every slide.
 */
spell_done: boolean, 
/**
 * Slide Master view, while it is on.
 */
master_view: DeckMasterView | null, 
/**
 * The drawing guides (shown with [`DeckState::guides`]).
 */
guide_list: Array<DeckGuide>, 
/**
 * The text area of the shape being edited, slide px (the ruler's indent markers).
 */
text_area: DeckRect | null, 
/**
 * The selected picture shows its crop handles (Picture Format ▸ Crop).
 */
cropping: boolean, 
/**
 * The selected cells of the table being edited (more than one).
 */
cells: DeckCellRange | null, };
